// Prueft, ob das Server-Skript heute sauber gelaufen ist (status.json). Wirft nie einen Fehler.
const fs = require('fs');
const FILE = '/home/node/vivino-daten/status.json';
const MAX_AGE_H = 6;
const clean = s => String(s).replace(/[_*`\[\]]/g, ' ');
try {
  const s = JSON.parse(fs.readFileSync(FILE, 'utf8'));
  const ageH = (Date.now() - new Date(s.zeit).getTime()) / 3600000;
  if (s.status !== 'ok') return [{ json: { ok: false, meldung: clean('Download auf dem Server: ' + s.status + ' - ' + (s.meldung || '')) } }];
  if (!(ageH < MAX_AGE_H)) return [{ json: { ok: false, meldung: clean('Status zu alt (' + ageH.toFixed(1) + ' Stunden). Hat das Server-Skript gelaufen?') } }];
  return [{ json: { ok: true, land: s.land, seiten: s.seiten, serverMeldung: s.meldung } }];
} catch (e) {
  return [{ json: { ok: false, meldung: clean('status.json nicht lesbar: ' + e.message) } }];
}

// Liest die vom Server-Skript geholten Vivino-Seiten und wandelt sie ins Katalogformat der App.
// Benoetigt in n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto,fs,https
const crypto = require('crypto');
const fs = require('fs');
const DIR = '/home/node/vivino-daten';
const TYPES = { 1: 'red', 2: 'white', 3: 'sparkling', 4: 'rose' };   // 7 (Dessert) bleibt leer
const LAND_DEUTSCH = true;   // Laendernamen deutsch (wie in der App) statt in der Landessprache ("Italia")
const clean = s => String(s).replace(/[_*`\[\]]/g, ' ');

try {
  // Muss genau so rechnen wie DuplicateFinder.normalized in der App: Akzente weg, Kleinschrift,
  // ss fuer ess-zett, alles andere (auch oe, ae, l mit Strich, griechisch) bleibt stehen.
  const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/ß/g, 'ss').replace(/[^\p{L}\p{N}]/gu, '');
  const key = (producer, name, vintage) =>
    'wine_' + crypto.createHash('md5').update([norm(producer), norm(name), String(Math.max(0, vintage))].join('_')).digest('hex');

  const regionNames = new Intl.DisplayNames(['de'], { type: 'region' });
  const land = c => {
    const code = (c?.code || '').toUpperCase();
    if (LAND_DEUTSCH && /^[A-Z]{2}$/.test(code)) {
      try { const n = regionNames.of(code); if (n && n !== code) return n; } catch (e) { /* Rueckfall unten */ }
    }
    return c?.native_name || c?.name || '';
  };

  // Vorhandene Bilder: Dateiname = Vivino-ID der Flasche
  const imgById = {};
  if (fs.existsSync(DIR + '/bilder')) {
    for (const f of fs.readdirSync(DIR + '/bilder')) imgById[f.split('.')[0]] = f;
  }

  const files = fs.readdirSync(DIR)
    .filter(f => /^vivino-page-\d+\.json$/.test(f))
    .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));
  if (!files.length) throw new Error('Keine vivino-page-*.json gefunden. Hat das Server-Skript gelaufen?');

  const out = new Map();
  for (const f of files) {
    const data = JSON.parse(fs.readFileSync(DIR + '/' + f, 'utf8'));
    const matches = data?.explore_vintage?.matches || [];
    for (const m of matches) {
      const v = m.vintage, w = v.wine;
      const vid = String(v.id);
      const vintage = Number.isInteger(v.year) ? v.year : 0;           // "N.V." wird 0 = ohne Jahrgang
      const producer = w.winery?.name || '';
      const name = w.name || '';
      const k = key(producer, name, vintage);
      const prev = out.get(k);
      if (prev) {                                                       // gleicher Wein, andere Vivino-ID
        prev.vids.push(vid);
        if (!prev.imageFile && imgById[vid]) prev.imageFile = imgById[vid];
        continue;
      }
      out.set(k, {
        key: k, name, producer, vintage,
        region: w.region?.name_en || w.region?.name || '',
        country: land(w.region?.country),
        typeRaw: TYPES[w.type_id] || '',
        source: 'vivino', sourceID: String(w.id),
        vids: [vid],
        imageFile: imgById[vid] || '',
        rating: v.statistics?.ratings_average ?? null,
        ratingsCount: v.statistics?.ratings_count ?? 0,
      });
    }
  }
  const wines = [...out.values()];
  if (!wines.length) throw new Error('Die Seiten enthalten keine Weine.');
  return [{ json: { ok: true, generatedAt: new Date().toISOString(), count: wines.length, mitBild: wines.filter(w => w.imageFile).length, wines, seiten: files.length } }];
} catch (e) {
  return [{ json: { ok: false, meldung: clean('Aufbereitung fehlgeschlagen: ' + e.message) } }];
}

// Schreibt die Weine in den oeffentlichen CloudKit-Katalog (CatalogWine) inklusive Bild (Asset).
// - Neue Weine werden angelegt, vorhandene nie veraendert (adminEdited bleibt unangetastet).
// - Fehlt einem vorhandenen Wein nur das Bild, wird es nachgetragen.
// - Aufraeumen: Bilddateien werden erst geloescht, wenn das Bild nachweislich in CloudKit liegt.
//   Die IDs der erledigten Weine kommen (ohne Doppel) in fertig.txt.
// Umgebungsvariablen: CK_KEY_ID, CK_PRIVATE_KEY, CK_ENV, CK_LIMIT
// Benoetigt: NODE_FUNCTION_ALLOW_BUILTIN=crypto,fs,https
const crypto = require('crypto');
const fs = require('fs');
const https = require('https');
const KEY_ID = $env.CK_KEY_ID, ENV = $env.CK_ENV || 'development';
const PEM = ($env.CK_PRIVATE_KEY || '').replace(/\\n/g, '\n');
const LIMIT = Number($env.CK_LIMIT || 0);          // zum Testen z. B. 5; 0 = alle
const CONTAINER = 'iCloud.com.sondinetwork.weinkeller.app';
const BASE = `/database/1/${CONTAINER}/${ENV}/public`;
const IMG_DIR = '/home/node/vivino-daten/bilder';
const DONE_FILE = '/home/node/vivino-daten/fertig.txt';
const FILLERS = new Set(['domaine','chateau','weingut','cantina','cantine','bodega','bodegas','tenuta','azienda','agricola','cave','caves','maison','winery','estate','vin','vino','wein','wine','rouge','rosso','rotwein','blanc','bianco','weisswein','the','les','del','della','von','und']);
const clean = s => String(s).replace(/[_*`\[\]]/g, ' ');

// Wie CatalogKey.tokens in der App: sonst findet die App den Eintrag nicht ueber den Namen.
const tokens = (name, producer) => {
  const words = (producer + ' ' + name).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/ß/g, 'ss')
    .split(/[^\p{L}\p{N}]+/u).filter(w => w.length >= 3 && !FILLERS.has(w) && !/^\p{N}+$/u.test(w));
  return [...new Set(words)];
};
const asText = r => Buffer.isBuffer(r) ? r.toString('utf8') : r;

// Signierter Aufruf an CloudKit
const ck = async (subpath, payload) => {
  const body = JSON.stringify(payload);
  const date = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
  const bodyHash = crypto.createHash('sha256').update(body).digest('base64');
  const signature = crypto.createSign('sha256').update(`${date}:${bodyHash}:${BASE}${subpath}`).sign(PEM, 'base64');
  const res = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.apple-cloudkit.com' + BASE + subpath, body, json: false,
    headers: { 'Content-Type': 'text/plain',
      'X-Apple-CloudKit-Request-KeyID': KEY_ID,
      'X-Apple-CloudKit-Request-ISO8601Date': date,
      'X-Apple-CloudKit-Request-SignatureV1': signature },
  });
  const t = asText(res);
  const parsed = typeof t === 'string' ? JSON.parse(t) : t;
  if (parsed.serverErrorCode) throw new Error(`CloudKit: ${parsed.serverErrorCode} ${parsed.reason || ''}`);
  return parsed;
};

// Bild zu CloudKit hochladen (mit dem eingebauten https-Modul), liefert die Quittung fuer das Asset-Feld
const uploadImage = async (recordName, file) => {
  const tok = await ck('/assets/upload', { tokens: [{ recordType: 'CatalogWine', fieldName: 'image', recordName }] });
  const url = tok.tokens?.[0]?.url;
  if (!url) throw new Error('keine Upload-Adresse erhalten');
  const data = fs.readFileSync(IMG_DIR + '/' + file);
  if (data.length < 1000) throw new Error('Bilddatei zu klein: ' + data.length + ' Bytes');
  const ext = file.split('.').pop().toLowerCase();
  const mime = (ext === 'jpg' || ext === 'jpeg') ? 'image/jpeg' : 'image/png';
  const boundary = '----n8n' + crypto.randomBytes(8).toString('hex');
  const head = Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="bild.${ext}"\r\nContent-Type: ${mime}\r\n\r\n`);
  const tail = Buffer.from(`\r\n--${boundary}--\r\n`);
  const body = Buffer.concat([head, data, tail]);
  const text = await new Promise((resolve, reject) => {
    const req = https.request(url, {
      method: 'POST',
      headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': body.length },
    }, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    });
    req.on('error', reject);
    req.setTimeout(30000, () => req.destroy(new Error('Timeout beim Bild-Upload')));
    req.write(body);
    req.end();
  });
  const parsed = JSON.parse(text);
  if (!parsed.singleFile) throw new Error('Upload ohne Quittung: ' + text.slice(0, 200));
  if (parsed.singleFile.size && parsed.singleFile.size < 1000) throw new Error('Apple meldet nur ' + parsed.singleFile.size + ' Bytes');
  return parsed.singleFile;
};

// Erledigte Weine: neue IDs in fertig.txt eintragen (ohne Doppel), Bilddateien nur loeschen,
// wenn das Bild in CloudKit liegt. Ein Bild, das nicht hochgeladen werden konnte, bleibt fuer
// den naechsten Lauf liegen.
const finish = (list, imageInCloud) => {
  let done;
  try { done = new Set(fs.readFileSync(DONE_FILE, 'utf8').split(/\s+/).filter(Boolean)); } catch (e) { done = new Set(); }
  const fresh = [];
  for (const w of list) for (const id of (w.vids || [])) if (!done.has(id)) { done.add(id); fresh.push(id); }
  if (fresh.length) fs.appendFileSync(DONE_FILE, fresh.join('\n') + '\n');
  let deleted = 0;
  if (fs.existsSync(IMG_DIR)) {
    const byId = {};
    for (const f of fs.readdirSync(IMG_DIR)) byId[f.split('.')[0]] = f;
    for (const w of list) {
      if (!imageInCloud.has(w.key)) continue;
      for (const id of (w.vids || [])) if (byId[id]) { fs.unlinkSync(IMG_DIR + '/' + byId[id]); deleted++; }
    }
  }
  return { fertigNeu: fresh.length, deleted };
};

try {
  let wines = $input.first().json.wines;
  if (LIMIT > 0) wines = wines.slice(0, LIMIT);

  let created = 0, existed = 0, attached = 0, withImage = 0, withoutImage = 0, deleted = 0, fertigNeu = 0;
  const errors = [];
  for (let i = 0; i < wines.length; i += 100) {
    const batch = wines.slice(i, i + 100);

    // 1. Was gibt es schon, und hat es ein Bild?
    const lookup = await ck('/records/lookup', { records: batch.map(w => ({ recordName: w.key })), desiredKeys: ['adminEdited', 'image'] });
    const found = new Map((lookup.records || []).map(r => [r.recordName, r]));
    const fresh = [], present = [], toAttach = [];
    const imageInCloud = new Set();
    for (const w of batch) {
      const r = found.get(w.key);
      if (!r || r.serverErrorCode === 'NOT_FOUND') fresh.push(w);
      else if (r.serverErrorCode) errors.push(`${w.key}: ${r.serverErrorCode} ${r.reason || ''}`.slice(0, 250));
      else {
        present.push(w);
        if (r.fields && r.fields.image) imageInCloud.add(w.key);
        else if (w.imageFile) toAttach.push({ w, tag: r.recordChangeTag });
      }
    }
    existed += present.length;

    // 2. Neue Weine: Bild hochladen, Record vorbereiten
    const ops = [];
    const createNames = new Set(), updateNames = new Set(), hasUpload = new Set();
    for (const w of fresh) {
      const fields = {
        name: { value: w.name },
        producer: { value: w.producer },
        vintage: { value: w.vintage, type: 'INT64' },
        grape: { value: '' },
        region: { value: w.region },
        country: { value: w.country },
        typeRaw: { value: w.typeRaw },
        alcoholPercent: { value: 0, type: 'DOUBLE' },
        searchTokens: { value: tokens(w.name, w.producer) },
        source: { value: 'vivino' },
        sourceID: { value: w.sourceID },
        adminEdited: { value: 0, type: 'INT64' },
      };
      if (w.imageFile) {
        try {
          const asset = await uploadImage(w.key, w.imageFile);
          fields.image = { value: asset, type: 'ASSETID' };
          hasUpload.add(w.key);
          withImage++;
        } catch (e) {
          withoutImage++;
          errors.push(`Bild ${w.name}: ${e.message}`.slice(0, 250));
        }
      } else { withoutImage++; }
      createNames.add(w.key);
      ops.push({ operationType: 'create', record: { recordType: 'CatalogWine', recordName: w.key, fields } });
    }

    // 3. Vorhandene Weine ohne Bild: nur das Bild nachtragen, sonst nichts anfassen
    for (const { w, tag } of toAttach) {
      try {
        const asset = await uploadImage(w.key, w.imageFile);
        updateNames.add(w.key);
        ops.push({ operationType: 'update', record: { recordType: 'CatalogWine', recordName: w.key, recordChangeTag: tag, fields: { image: { value: asset, type: 'ASSETID' } } } });
      } catch (e) {
        errors.push(`Bild nachtragen ${w.name}: ${e.message}`.slice(0, 250));
      }
    }

    // 4. Schreiben
    const okNames = new Set();
    if (ops.length) {
      const res = await ck('/records/modify', { operations: ops });
      for (const r of res.records || []) {
        if (r.serverErrorCode) {
          errors.push(`${r.recordName}: ${r.serverErrorCode} ${r.reason || ''}`.slice(0, 250));
          continue;
        }
        okNames.add(r.recordName);
        if (createNames.has(r.recordName)) { created++; if (hasUpload.has(r.recordName)) imageInCloud.add(r.recordName); }
        else if (updateNames.has(r.recordName)) { attached++; imageInCloud.add(r.recordName); }
      }
    }

    // 5. Aufraeumen: nur Weine, die jetzt sicher in CloudKit sind
    try {
      const safe = batch.filter(w => present.includes(w) || (createNames.has(w.key) && okNames.has(w.key)));
      const f = finish(safe, imageInCloud);
      deleted += f.deleted; fertigNeu += f.fertigNeu;
    } catch (e) {
      errors.push('Aufraeumen nicht moeglich (Ordner schreibgeschuetzt?): ' + e.message);
    }
  }
  const ok = errors.length === 0;
  const meldung = ok ? '' : clean(`CloudKit-Import mit ${errors.length} Fehlern. Erster Fehler: ${errors[0]}`);
  return [{ json: { ok, meldung, env: ENV, versucht: wines.length, neu: created, schonVorhanden: existed, bilderNachgetragen: attached, mitBild: withImage, ohneBild: withoutImage, bilderGeloescht: deleted, fertigNeu, fehler: errors.slice(0, 10), fehlerAnzahl: errors.length } }];
} catch (e) {
  return [{ json: { ok: false, meldung: clean('CloudKit-Import abgebrochen: ' + e.message) } }];
}
